"""Acceptance checks using catalogue fixtures generated by the PGlite lifecycle test."""
import json
import sys
from pathlib import Path
from playwright.sync_api import sync_playwright, expect

products = [json.loads(Path('test-results/' + name + '-bar-browser-fixture.json').read_text())
            for name in ('round', 'bright')]
errors = []


def api(route):
    body = route.request.post_data_json or {} if route.request.method != 'OPTIONS' else {}
    op, args = body.get('operation'), body.get('arguments', {})
    result = []
    if op == 'fti_catalog_product_get':
        result = next((p for p in products if p['id'] == args.get('p_id')), None)
    elif op == 'fti_catalog_filtered_list':
        result = {'items': products, 'total': 2, 'categories': [], 'grades': []}
    route.fulfill(status=200, content_type='application/json', body=json.dumps({'data': result}),
                  headers={'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': '*'})


base = 'http://127.0.0.1:' + (sys.argv[1] if len(sys.argv) > 1 else '8141')
Path('artifacts').mkdir(exist_ok=True)
with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)
    for width, height in ((390, 844), (1366, 1000)):
        context = browser.new_context(viewport={'width': width, 'height': height})
        context.route('https://*.supabase.co/**', api)
        page = context.new_page()
        page.on('pageerror', lambda error: errors.append(str(error)))
        for product in products:
            bright = product['slug'].startswith('round-bright-bar')
            page.goto(base + '/product/' + product['id'])
            page.wait_for_load_state('networkidle')
            expect(page.get_by_text('36 sizes · 34 grades', exact=True)).to_be_visible()
            page.get_by_role('button', name='Size (mm): Choose size', exact=True).click()
            expect(page.get_by_role('radio')).to_have_count(37)
            expect(page.get_by_role('radio', name='19 mm', exact=True)).to_have_count(0)
            page.get_by_role('radio', name='8 mm', exact=True).click()
            page.get_by_role('button', name='Grade: Choose grade', exact=True).click()
            expect(page.get_by_role('radio')).to_have_count(35)
            for included in ('SAE-4130', 'SAE-4140', 'SAE-8620', 'SCM-420', 'SCM-435', 'ST-52.3'):
                expect(page.get_by_role('radio', name=included, exact=True)).to_have_count(1)
            for excluded in ('MS', 'FE-500', 'FE-550', 'FE-600', 'FE-600S', 'FE-550D', 'FE-650', 'FE-700'):
                expect(page.get_by_role('radio', name=excluded, exact=True)).to_have_count(0)
            page.get_by_role('radio', name='EN-8D', exact=True).click()
            expect(page.get_by_role('button', name='Close filter', exact=True)).to_have_count(0)
            expect(page.get_by_text('Request quote', exact=True)).to_be_visible()
            page.screenshot(path=f'artifacts/{"bright" if bright else "round"}-bar-quote-{width}.png', full_page=True)
            page.get_by_role('button', name='Size (mm): 8 mm', exact=True).click()
            page.get_by_role('radio', name='16 mm', exact=True).click()
            page.get_by_role('button', name='Grade: Choose grade', exact=True).click()
            page.get_by_role('radio', name='EN-8D', exact=True).click()
            expect(page.get_by_role('button', name='Close filter', exact=True)).to_have_count(0)
            expect(page.get_by_text(f'INR {"21,500" if bright else "13,500"} / PMT', exact=True)).to_be_visible()
            assert page.evaluate('document.documentElement.scrollWidth <= window.innerWidth')
            page.screenshot(path=f'artifacts/{"bright" if bright else "round"}-bar-priced-{width}.png', full_page=True)
        page.goto(base + '/products')
        expect(page.get_by_text('36 sizes · 34 grades', exact=True)).to_have_count(2)
        expect(page.get_by_text('68 active variants', exact=True)).to_have_count(0)
        context.close()
    browser.close()
assert not errors, errors
print('PASS: both categories, 36 sizes and 34 grades, quote and priced states at mobile/desktop widths; no page errors.')
